use crate::domains::rust_perf::PerfRule;

/// Data table, not logic — grows with distillation batches.
#[allow(clippy::too_many_lines)]
pub(super) fn entries() -> Vec<PerfRule> {
    vec![
        // ── wasm: on wasm targets every panic site drags core::panicking's
        // formatted-message machinery into the artifact even under
        // panic = "abort"; a precondition-impossible unwrap can compile to
        // a match + a 1-byte trap instead. Source: stellar/rs-soroban-sdk
        // unwrap.rs (the `UnwrapOptimized` trait).
        PerfRule {
            rule_id: "wasm-unwrap-panic-machinery-elimination".to_string(),
            name: "an `unwrap()`/`expect()` in wasm-targeted code carries core::panicking's message + fmt machinery into the artifact even under panic = abort → route precondition-impossible unwraps through a trait whose wasm arm matches to a 1-byte `core::arch::wasm32::unreachable()` trap (the native arm keeps the plain unwrap); a statically-infallible Result destructures `Err(never) => match never {}` instead of panicking".to_string(),
            category: "wasm".to_string(),
            buggy_code: "// A module targeting wasm32v1-none: every panic site drags\n// core::panicking's formatted-message machinery into the artifact\n// (static message strings + fmt plumbing) even under panic = \"abort\" —\n// each unwrap is bytes the size budget pays for.\nfn parse_depth(raw: Option<u32>) -> u32 {\n    raw.unwrap()\n}\n\nfn read_secret_len(res: Result<usize, String>) -> usize {\n    res.unwrap()\n}\n\n#[test]\nfn sites_answer() {\n    assert_eq!(parse_depth(Some(7)), 7);\n    assert_eq!(read_secret_len(Ok(42)), 42);\n}\n"
                .to_string(),
            fixed_code: "// The same two sites behind a trait whose wasm arm compiles to a\n// match + a 1-byte trap; the native arm keeps the plain unwrap (the\n// trait is a no-op shape there). DELIBERATE semantics change on the\n// impossible arm — trap, not panic — never rewrite an unwrap whose\n// None/Err arm is reachable.\npub trait UnwrapOptimized {\n    type Output;\n    fn unwrap_optimized(self) -> Self::Output;\n}\n\nimpl<T> UnwrapOptimized for Option<T> {\n    type Output = T;\n    #[inline(always)]\n    fn unwrap_optimized(self) -> T {\n        #[cfg(target_family = \"wasm\")]\n        match self {\n            Some(t) => t,\n            None => core::arch::wasm32::unreachable(),\n        }\n        #[cfg(not(target_family = \"wasm\"))]\n        self.unwrap()\n    }\n}\n\nimpl<T, E: core::fmt::Debug> UnwrapOptimized for Result<T, E> {\n    type Output = T;\n    #[inline(always)]\n    fn unwrap_optimized(self) -> T {\n        #[cfg(target_family = \"wasm\")]\n        match self {\n            Ok(t) => t,\n            Err(_) => core::arch::wasm32::unreachable(),\n        }\n        #[cfg(not(target_family = \"wasm\"))]\n        self.unwrap()\n    }\n}\n\n// Statically-checked infallibility: a Result<T, Infallible> destructures\n// the never variable into zero cases instead of panicking or\n// unreachable!()-asserting.\npub trait UnwrapInfallible {\n    type Output;\n    fn unwrap_infallible(self) -> Self::Output;\n}\n\nimpl<T> UnwrapInfallible for Result<T, core::convert::Infallible> {\n    type Output = T;\n    fn unwrap_infallible(self) -> T {\n        match self {\n            Ok(ok) => ok,\n            #[allow(unreachable_patterns)]\n            Err(never) => match never {},\n        }\n    }\n}\n\nfn parse_depth(raw: Option<u32>) -> u32 {\n    raw.unwrap_optimized()\n}\n\nfn read_secret_len(res: Result<usize, String>) -> usize {\n    res.unwrap_optimized()\n}\n\nfn known_ok() -> Result<u32, core::convert::Infallible> {\n    Ok(5)\n}\n\n#[test]\nfn sites_answer() {\n    assert_eq!(parse_depth(Some(7)), 7);\n    assert_eq!(read_secret_len(Ok(42)), 42);\n    assert_eq!(known_ok().unwrap_infallible(), 5);\n}\n"
                .to_string(),
            context_notes: Some("Grade B− — NotBenchable on this box (DOMAIN reason: the win metric is wasm BINARY SIZE, which a native Pareto validator cannot host — the dial9/Research-179 per-rule annotation class, not a demotion; the corpus's wasm family is exactly this shape: wasm-batch-ffi ships bench_spec None). THE MECHANISM: on wasm targets every .unwrap() compiles to a call into core::panicking carrying a static message string + fmt plumbing — machinery the artifact pays for even under panic = 'abort' (abort changes the RUNTIME panic path, not the code the panic path needs); core::arch::wasm32::unreachable() is a 1-byte trap. THE BYTES STORY is the distill analysis (Research 252) — source-qualified by production use in every Soroban contract, NO local wasm measurement this session, never quoted as a local bar. THE SECOND HALF (same source file): UnwrapInfallible destructures the never type instead of panicking — 'Err(never) => match never {}' — the in-source law verbatim: 'destructuring the `never` variable into an empty set of cases is the most honest since it's statically checked to _be_ infallible, not just an assertion of our hopes.' ANTI-REGIME (MANDATORY): unwrap_optimized is a DELIBERATE semantics change on the impossible arm — trap vs panic (the panic handler, hook, and message are gone); NEVER rewrite an unwrap whose None/Err arm is reachable. REGIME: wasm-size-critical artifacts (contract/module binaries with size budgets) at precondition-impossible unwrap sites. Distinct-from (grep-verified both vocabularies, 0 collisions this session): unwrap-or-else-lazy owns the eager-vs-lazy default EVALUATION axis; oneshot-response-send-unwrap-panics owns panic-as-liveness-hazard (unwrap REMOVAL on a reachable cancellation); dist's cli-panic-unwind-tables owns the PROFILE level (panic = abort landing pads) and shipped-binary-missing-size-profile the manifest knobs — complementary levers, the source itself runs both (panic = abort in the profile AND UnwrapOptimized at call sites). Fixtures ORIGINAL (the trait shape transcribed as a plain-Rust stand-in; no Soroban source pasted). CITE: stellar/rs-soroban-sdk @ 0d72c4c9ed7dd5f948b4ef5ac2cbcdd9f21380f9 (soroban-sdk/src/unwrap.rs, main HEAD 2026-10-09), Apache-2.0; quotes re-verified at the pin via the .raw clone this session. Batch 222 / Plan 216 / Research 252.".to_string()),
            // Not benchable: the win metric is wasm binary size — a native
            // validator cannot host the axis (the dial9/B136 class).
            #[cfg(feature = "rust_perf_bench")]
            bench_spec: None,
        },
        // ── wasm: a data-only custom-section static with no compiled-code
        // reference is shaken out by the linker's GC; root it in a
        // reachable path with a volatile read. Source: stellar/rs-soroban-sdk
        // HEAD #2114 "Fix event spec shaking" (shaking.rs + spec_shaking.rs
        // + the events.rs publish_event call site).
        PerfRule {
            rule_id: "linker-dce-custom-section-volatile-marker".to_string(),
            name: "a data-only `#[link_section]` static (or an externally-consumed symbol) with NO compiled-code reference is shaken out by the linker's section GC (wasm GC / --gc-sections) → root it in a REACHABLE path with a `read_volatile` of its pointer; for functions, take a fn pointer and volatile-read it — alive without being called".to_string(),
            category: "wasm".to_string(),
            buggy_code: "// Build metadata shipped for an EXTERNAL tool: a packager /\n// inspector / attestation checker reads the custom section out of the\n// artifact. No compiled code references the static, so the linker's\n// section GC (wasm GC; --gc-sections natively) shakes the section out\n// and the tool finds nothing in the shipped binary.\n#[link_section = \"appmeta\"]\nstatic META: [u8; 8] = *b\"AMETAv01\";\n\npub fn current_version() -> u32 {\n    1\n}\n"
                .to_string(),
            fixed_code: "#[link_section = \"appmeta\"]\nstatic META: [u8; 8] = *b\"AMETAv01\";\n\npub fn boot() {\n    // Root the section in a REACHABLE path: a volatile read is not dead\n    // to the optimizer, and the live reference stops the linker's GC\n    // from shaking the section out of the artifact.\n    let _ = unsafe { core::ptr::read_volatile(META.as_ptr()) };\n}\n\n// The function-shaped sibling of the same law: keep a symbol alive\n// WITHOUT calling it — take it as a fn pointer and volatile-read the\n// pointer (also how recursive type graphs reference markers without\n// risking a runtime cycle).\nfn keep_reachable(_f: fn()) {\n    let _ = unsafe { core::ptr::read_volatile(&_f) };\n}\n\npub fn current_version() -> u32 {\n    1\n}\n"
                .to_string(),
            context_notes: Some("Grade C+ — NotBenchable (same size-axis domain reason as wasm-unwrap-panic-machinery-elimination: the win is the artifact SHIPPING THE SECTION AT ALL — unmeasurable on a native validator; the dial9/Research-179 annotation class). THE MECHANISM (the HEAD commit AT the pin, #2114 'Fix event spec shaking', diff + body read in full this session): contract spec metadata ships as DATA-ONLY statics in custom sections (contractspecv0, applied via cfg_attr(target_family = 'wasm', link_section = ...)) that NO compiled code references — the wasm linker's GC shakes them out of the artifact; the fix routes every publish path through a retention marker: 'let _ = unsafe { ::core::ptr::read_volatile(MARKER.as_ptr()) };' rooted in reachable code (events.rs publish_event now opens with the SpecShakingMarker call). The commit body verbatim: events published via the generic paths 'never hit the event's spec shaking marker ... so the event and its field types are stripped from the built contract's spec even though the event is still published on-chain.' THE FUNCTION HALF (spec_shaking.rs keep_reachable, doc verbatim): 'Keeps `f`'s symbol alive through the linker's dead-code-elimination pass without invoking `f` at runtime.' — take a fn pointer, volatile-read it; recursive definitions reference inner markers WITHOUT calling them so no runtime cycle is possible. REGIME: wasm (or --gc-sections native) artifacts carrying data-only custom sections consumed by EXTERNAL tooling (packagers, inspectors, attestation/spec readers) — the bytes are the product and the linker cannot see that. ANTI-REGIME: anything any compiled code can already reach (a plain reference retains it — no volatile needed); do not use retention markers to keep genuinely dead code alive (the marker must root something the artifact genuinely ships); the volatile read defeats OPTIMIZER DCE of the read — surviving the LINKER's section GC is the live-reference part, and the fn-pointer form is the tool for code symbols. Distinct-from: zero corpus owners (link_section | spec_shaking | marker | read_volatile greps = 0 hits this session) — nothing owns linker-DCE retention; dist's ship-size family owns manifest knobs, not reference rooting. Fixtures ORIGINAL (an appmeta section stand-in; no Soroban source pasted). CITE: stellar/rs-soroban-sdk @ 0d72c4c9ed7dd5f948b4ef5ac2cbcdd9f21380f9, HEAD commit 0d72c4c9 'Fix event spec shaking (#2114)' (soroban-sdk-macros/src/shaking.rs + soroban-sdk/src/spec_shaking.rs keep_reachable + events.rs publish_event), Apache-2.0; quotes re-verified at the pin via the .raw clone this session. Batch 222 / Plan 216 / Research 252.".to_string()),
            // Not benchable: the win is the section surviving into the
            // artifact at all — no native axis hosts it (the dial9 class).
            #[cfg(feature = "rust_perf_bench")]
            bench_spec: None,
        },
    ]
}
